mapper.select:
SELECT EQUITY_CONF_DATE AS EQUITYCONFDATE, CHECK_TOTAL AS CHECKTOTAL, ACCOUNT AS ACCOUNT, PROD_REGIST_CODE AS PRODREGISTCODE, PROD_NAME AS PRODNAME, OPERATE_MODE AS OPERATEMODE, VDATE AS VDATE, MDATE AS MDATE, IS_CONSIGN AS ISCONSIGN, CHECK_MJ AS CHECKMJ, CHECK_SGAMT AS CHECKSGAMT, CHECK_SGQTY AS CHECKSGQTY, CHECK_SHQTY AS CHECKSHQTY, CHECK_SHAMT AS CHECKSHAMT FROM ( SELECT T.EQUITY_CONF_DATE, IF( MJ_SUB.TOTAL_AMT = T.MJ_AMT AND CX_SUB.SGAMT = T.SG_AMT AND CX_SUB.SGQTY = T.SG_QTY AND CX_SUB.SHAMT = T.SH_AMT AND CX_SUB.SHQTY = T.SH_QTY, '01', '02' ) CHECK_TOTAL, T.ACCOUNT, MJ_SUB.PROD_REGIST_CODE, CPB.PROD_NAME, CPB.OPERATE_MODE, CPB.VDATE, CPB.MDATE, MJ_SUB.IS_CONSIGN, IF(MJ_SUB.TOTAL_AMT = T.MJ_AMT, '01', '02') CHECK_MJ, IF(CX_SUB.SGAMT = T.SG_AMT, '01', '02') CHECK_SGAMT, IF(CX_SUB.SGQTY = T.SG_QTY, '01', '02') CHECK_SGQTY, IF(CX_SUB.SHQTY = T.SH_QTY, '01', '02') CHECK_SHQTY, IF(CX_SUB.SHAMT = T.SH_AMT, '01', '02') CHECK_SHAMT FROM ( SELECT T1.ACCOUNT, T1.EQUITY_CONF_DATE, SUM(IFNULL(T1.MJ_AMT, 0)) AS MJ_AMT, SUM(IFNULL(T1.SG_QTY, 0)) AS SG_QTY, SUM(IFNULL(T1.SG_AMT, 0)) AS SG_AMT, SUM(IFNULL(T1.SH_QTY, 0)) AS SH_QTY, SUM(IFNULL(T1.SH_AMT, 0)) AS SH_AMT FROM ( SELECT B.ACCOUNT, C.MJ_AMT, B.EQUITY_CONF_DATE, SUM(IF(B.BUSI_TYPE IN ('02', '05', '14'), IFNULL(SHARES, 0), 0)) AS SG_QTY, SUM(IF(B.BUSI_TYPE IN ('02', '05', '14'), IFNULL(AMOUNT_CNY, 0), 0)) AS SG_AMT, SUM(IF(B.BUSI_TYPE IN ('03', '15', '16'), IFNULL(SHARES, 0), 0)) AS SH_QTY, SUM(IF(B.BUSI_TYPE IN ('03', '04', '05', '15', '16'), IFNULL(AMOUNT_CNY, 0),0)) AS SH_AMT FROM ( SELECT *, RANK() OVER (PARTITION BY ACCOUNT,INDENTIFY_MARK,EQUITY_CONF_DATE,BUSI_TYPE ORDER BY IFNULL(UPDATE_TIME, CREATE_TIME) DESC ) MY_RANK FROM CHB_EQUDET_SUB ) B LEFT JOIN ( SELECT T.ACCOUNT, SUM(IFNULL(AMOUNT_CNY, 0)) AS MJ_AMT FROM (SELECT *, RANK() OVER (PARTITION BY ACCOUNT,INDENTIFY_MARK,EQUITY_CONF_DATE,BUSI_TYPE ORDER BY IFNULL(UPDATE_TIME, CREATE_TIME) DESC ) MY_RANK FROM CHB_EQUDET_SUB A WHERE A.BUSI_TYPE = '01' ) AS T WHERE MY_RANK = 1 GROUP BY T.ACCOUNT ) C ON C.ACCOUNT = B.ACCOUNT WHERE B.BUSI_TYPE IN ('01','02', '03', '04', '05', '14', '15', '16') AND B.MY_RANK = 1
AND DATE_FORMAT(B.EQUITY_CONF_DATE, '%Y-%m-%d') >= #{checkDateStart}
AND DATE_FORMAT(B.EQUITY_CONF_DATE, '%Y-%m-%d') <= #{checkDateEnd}
GROUP BY B.ACCOUNT, B.EQUITY_CONF_DATE )T1 GROUP BY T1.ACCOUNT, T1.EQUITY_CONF_DATE ) T LEFT JOIN ( SELECT * FROM ( SELECT CPRS.PROD_ID, CPRS.PROD_REGIST_CODE, CPRS.IS_CONSIGN, CPRS.TOTAL_AMT, RANK() OVER (PARTITION BY CPRS.PROD_ID ORDER BY IFNULL(UPDATE_TIME, CREATE_TIME) DESC) MY_RANK FROM CHB_PRD_RAISETOT_SUB CPRS) CPRS WHERE CPRS.MY_RANK = 1 ) MJ_SUB ON T.ACCOUNT = MJ_SUB.PROD_ID LEFT JOIN ( SELECT CPDS.PROD_ID, CPDS.MDATE, SUM(IFNULL(CPDS.PURCHASE_QTY, 0)) AS SGQTY, SUM(SUBSTRING_INDEX(SUBSTRING_INDEX(CCY_PURCHASE,',',2),',',-1)) AS SGAMT, SUM(IFNULL(CPDS.REDEEM_QTY, 0)) AS SHQTY, SUM(SUBSTRING_INDEX(SUBSTRING_INDEX(CCY_PURCHASE,',',3),',',-1)) AS SHAMT FROM (SELECT *, RANK() OVER (PARTITION BY PROD_ID,MDATE ORDER BY IFNULL(UPDATE_TIME, CREATE_TIME) DESC) MY_RANK FROM CHB_PRD_DEAL_SUB ) CPDS WHERE CPDS.MY_RANK = 1
AND DATE_FORMAT(CPDS.MDATE, '%Y-%m-%d') >= #{checkDateStart}
AND DATE_FORMAT(CPDS.MDATE, '%Y-%m-%d') <= #{checkDateEnd}
GROUP BY CPDS.PROD_ID, CPDS.MDATE ) CX_SUB ON T.ACCOUNT = CX_SUB.PROD_ID AND T.EQUITY_CONF_DATE = CX_SUB.MDATE LEFT JOIN CHB_PRD_BASEINFO CPB ON T.ACCOUNT = CPB.PROD_ID ) T
AND (ACCOUNT like concat('%', #{prod},'%') or PROD_NAME like concat('%', #{prod},'%'))
#{operateMode,jdbcType=VARCHAR}
#{checkResult,jdbcType=VARCHAR}
and date_format(VDATE, '%Y-%m-%d') >= #{vdateStart}
and date_format(VDATE, '%Y-%m-%d') <= #{vdateEnd}
and date_format(MDATE, '%Y-%m-%d') >= #{mdateStart}
and date_format(MDATE, '%Y-%m-%d') <= #{mdateEnd}
ORDER BY EQUITY_CONF_DATE DESC,ACCOUNT ASC
